'use strict';

const { SmartSpectraErrorCode } = require('./constants');

const CameraSelection = Object.freeze({
    default: Object.freeze({ kind: 'default' }),
    front: Object.freeze({ kind: 'front' }),
    back: Object.freeze({ kind: 'back' }),
    byId: (id) => Object.freeze({ kind: 'byId', id }),
});

function configurationError(message) {
    return Object.assign(new Error(message), {
        code: SmartSpectraErrorCode.kConfigurationFailed, retryable: false,
    });
}

function normalizeCameraSelection(selection) {
    if (!selection || typeof selection !== 'object') {
        throw configurationError('useCamera: expected a CameraSelection');
    }
    switch (selection.kind) {
        case 'default': case 'front': case 'back':
            if (selection.id !== undefined) throw configurationError('Camera ID requires byId selection');
            return Object.freeze({ kind: selection.kind });
        case 'byId':
            if (typeof selection.id !== 'string' || !selection.id || selection.id.includes('\0')) {
                throw configurationError('Camera ID must be a non-empty string without NUL characters');
            }
            return CameraSelection.byId(selection.id);
        default: throw configurationError('Unknown camera selection kind');
    }
}

function normalizeCameraOptions(options) {
    if (!options || typeof options !== 'object' || Array.isArray(options)) {
        throw configurationError('useCamera: expected capture options');
    }
    if ('deviceIndex' in options) throw configurationError('Use CameraSelection.byId(id) instead of deviceIndex');
    const copy = {};
    for (const field of ['width', 'height', 'fps', 'frameTransform']) {
        const value = options[field] ?? 0;
        const max = field === 'frameTransform' ? 5 : 2147483647;
        if (!Number.isInteger(value) || value < 0 || value > max) {
            throw configurationError(`Invalid camera ${field}`);
        }
        copy[field] = value;
    }
    if (Boolean(copy.width) !== Boolean(copy.height)) {
        throw configurationError('Camera width and height must be specified together');
    }
    return Object.freeze(copy);
}

module.exports = { CameraSelection, normalizeCameraSelection, normalizeCameraOptions };
